"""Timezone-aware e-filing deadline tool using Python's stdlib zoneinfo.

Invented e-filing rule: a document is timely if received by 23:59:59
in the court's timezone on the deadline date.
"""

from datetime import date, datetime, time, timezone
from zoneinfo import ZoneInfo

_CUTOFF = time(23, 59, 59)


def _require_aware(received_utc: datetime) -> None:
    """Raise TypeError if the datetime is naive."""
    if not isinstance(received_utc, datetime):
        raise TypeError(
            f"received_utc must be a datetime, got {type(received_utc).__name__}"
        )
    if received_utc.tzinfo is None or received_utc.tzinfo.utcoffset(received_utc) is None:
        raise TypeError(
            "received_utc must be timezone-aware (naive datetime rejected)"
        )


def deadline_instant(deadline_date: date, court_tz: str) -> datetime:
    """Return the cutoff instant as an aware UTC datetime.

    That is 23:59:59 on ``deadline_date`` in ``court_tz``, converted to UTC.
    """
    tz = ZoneInfo(court_tz)
    local_cutoff = datetime.combine(deadline_date, _CUTOFF, tzinfo=tz)
    return local_cutoff.astimezone(timezone.utc)


def is_timely(
    received_utc: datetime, deadline_date: date, court_tz: str
) -> bool:
    """True if ``received_utc`` arrives by 23:59:59 court-local time on the deadline."""
    _require_aware(received_utc)
    return received_utc <= deadline_instant(deadline_date, court_tz)

